import { useCallback, useMemo } from 'react';

import {
  useCurrentPage,
  usePageFilterApplied,
  usePageFilterData,
  usePageFilterManagement,
  useSubFilters,
} from 'hooks';
import { WaterfallConfig } from 'pages/pillars/ValueCreation/PerformanceTool/config';
import { WaterfallSectionData } from 'pages/pillars/ValueCreation/PerformanceTool/types';

import { useWaterfallDatasets } from '../useWaterfallDatasets/useWaterfallDatasets';

interface UseWaterfallSectionParams {
  config: WaterfallConfig;
  data: WaterfallSectionData | undefined;
  variant: 'large' | 'small';
}

export const useWaterfallSection = ({
  config,
  data,
  variant,
}: UseWaterfallSectionParams) => {
  const { currentPage } = useCurrentPage();
  const { applied, isGlobalZone } = usePageFilterApplied(currentPage);
  const { dataFilters } = usePageFilterData(currentPage);
  const { applyDirect } = usePageFilterManagement(currentPage);
  const { activeSubFilters } = useSubFilters();
  const { legendItems, shouldShowLegend } = useWaterfallDatasets(data, variant);

  const chartData = data?.[variant];

  const contextKey = useMemo(
    () => config.getContextKey(applied, isGlobalZone),
    [config, applied, isGlobalZone],
  );

  const isViewByDisabled = useMemo(
    () => config.isViewByDisabled(contextKey, activeSubFilters, applied),
    [config, contextKey, activeSubFilters, applied],
  );

  const disabledIndexes = useMemo(
    () => config.getDisabledIndexes?.(chartData?.labels) ?? [],
    [config, chartData?.labels],
  );

  const handleBarClick = useCallback(
    (index: number | null) => {
      if (index === null) return;

      config.handleBarClick({
        index,
        labels: chartData?.labels,
        activeSubFilters,
        dataFilters,
        applied,
        applyDirect,
      });
    },
    [
      config,
      chartData?.labels,
      activeSubFilters,
      dataFilters,
      applied,
      applyDirect,
    ],
  );

  return {
    chartData,
    contextKey,
    isViewByDisabled,
    disabledIndexes,
    handleBarClick,
    legendItems,
    shouldShowLegend,
  };
};
